  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਾਣਕ ਦੇ ਜੀਵਨ ਦੇ ਦੁਖਦਾਈ ਪਹਿਲੂਆਂ ਬਾਰੇ ਵਿਸਥਾਰ ਨਾਲ ਚਰਚਾ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਾਣਕ ਦੇ ਸ਼ਾਗਿਰਦਾਂ ਨੂੰ ਸੰਗੀਤ ਸਿਖਾਉਣ ਦੇ ਫੈਸਲੇ ਦਾ ਕੀ ਮਹੱਤਵ ਸੀ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਾਣਕ ਦੇ ਜੀਵਨ ਤੋਂ ਸਿੱਖਣ ਦੇ ਨਤੀਜਿਆਂ (Learning Outcomes) ਦੀ ਵਿਆਖਿਆ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true);
INSERT INTO public.question_bank (id, institution_id, subject_id, topic_id, grade_level_id, class_group_id, question_text, question_type, options, correct_answer, marks, difficulty_level, tags, source, created_by, is_approved, parent_question_id, sub_question_count, sequence_order) VALUES
  ('5cd6adfe-663c-4690-9035-95b2b4ebccb1', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪੰਜਾਬ ਦੀ ਧਰਤੀ ਨੇ ਕਈ ਪ੍ਰਸਿੱਧ ਲੋਕ-ਗਾਇਕਾਂ ਨੂੰ ਜਨਮ ਦਿੱਤਾ ਹੈ। ਇਹਨਾਂ ਗਾਇਕਾਂ ਨੇ ਗੀਤ-ਸੰਗੀਤ ਦੇ ਖੇਤਰ ਵਿੱਚ ਆਪਣੀ ਬੁਲੰਦ ਆਵਾਜ਼ ਨਾਲ ਸਫਲਤਾ ਦੇ ਝੰਡੇ ਗੱਡੇ ਹਨ। ਗਾਇਕ ਲਾਲ ਚੰਦ ਯਮਲਾ ਜੱਟ, ਪ੍ਰਕਾਸ਼ ਕੌਰ ਅਤੇ ਸੁਰਿੰਦਰ ਕੌਰ ਭੈਣਾਂ, ਆਸਾ ਸਿੰਘ ਮਸਤਾਨਾ, ਗੁਰਦਾਸ ਮਾਨ ਆਦਿ ਕਲਾਕਾਰਾਂ ਨੇ ਪੰਜਾਬੀ ਗੀਤਾਂ ਨੂੰ ਸੰਸਾਰ ਦੇ ਕੋਨੇ-ਕੋਨੇ ਤੀਕ ਪਹੁੰਚਾਇਆ ਹੈ। ਇਹਨਾਂ ਸਿਰਕੱਢ ਨਾਵਾਂ ਵਿੱਚੋਂ ਹੀ ਇੱਕ ਨਾਮ ਹੈ - ਕੁਲਦੀਪ ਮਾਣਕ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('394ad9e0-0855-4c2d-aada-9d97975b7b09', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਜਿਵੇਂ ਸੁਰਿੰਦਰ ਕੌਰ ਨੂੰ ਸਾਰੇ 'ਪੰਜਾਬ ਦੀ ਕੋਇਲ' ਵਜੋਂ ਜਾਣਦੇ ਹਨ, ਉਵੇਂ ਹੀ ਕੁਲਦੀਪ ਮਾਣਕ ਨੂੰ ਪੰਜਾਬੀ 'ਕਲੀਆਂ ਦਾ ਬਾਦਸ਼ਾਹ' ਵਜੋਂ ਜਾਣਦੇ ਹਨ। ਕਲੀ ਪੰਜਾਬੀ ਕਵਿਤਾ ਦਾ ਇੱਕ ਮਸ਼ਹੂਰ ਛੰਦ ਹੈ। ਮਾਣਕ ਦੀ ਪ੍ਰਸਿੱਧੀ ਕਲੀਆਂ ਗਾਉਣ ਕਰਕੇ ਹੀ ਜ਼ਿਆਦਾ ਹੋਈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('14ddbc59-4b3b-4111-852c-fd6c907a6e13', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਾਣਕ ਦਾ ਜਨਮ ਬਠਿੰਡਾ ਜ਼ਿਲ੍ਹੇ ਦੇ ਪਿੰਡ ਜਲਾਲ ਵਿਖੇ 11 ਨਵੰਬਰ, 1949 ਈ: ਨੂੰ ਪਿਤਾ ਨਿੱਕਾ ਖਾਨ ਅਤੇ ਮਾਤਾ ਬਚਨੋ ਦੇ ਘਰ ਹੋਇਆ। 1968 ਈ: ਵਿੱਚ ਮਾਣਕ ਦਾ ਵਿਆਹ ਸਰਬਜੀਤ ਕੌਰ ਨਾਲ ਹੋਇਆ। ਇਹਨਾਂ ਦੇ ਘਰ ਪੁੱਤਰ ਯੁੱਧਵੀਰ ਮਾਣਕ ਅਤੇ ਧੀ ਸ਼ਕਤੀ ਮਾਣਕ ਨੇ ਜਨਮ ਲਿਆ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('51f2b132-5bfc-490a-9d02-9bca1ecb394a', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਹਨਾਂ ਦਾ ਪਰਿਵਾਰ ਪੀੜ੍ਹੀ ਦਰ ਪੀੜ੍ਹੀ ਸੰਗੀਤ ਨਾਲ ਜੁੜਿਆ ਹੋਇਆ ਸੀ। ਪਿੰਡ ਵਿੱਚ ਇਹਨਾਂ ਦਾ ਪਰਿਵਾਰ 'ਮਰਦਾਨੇ ਕਾ' ਵਜੋਂ ਜਾਣਿਆ ਜਾਂਦਾ ਹੈ। ਇਹਨਾਂ ਦੇ ਪੁਰਖੇ ਨਾਭਾ ਰਿਆਸਤ ਦੇ ਰਾਜੇ ਹੀਰਾ ਸਿੰਘ ਦੇ ਦਰਬਾਰ ਵਿੱਚ ਹਜ਼ੂਰੀ ਰਾਗੀ ਵਜੋਂ ਸੇਵਾ ਨਿਭਾਉਂਦੇ ਰਹੇ ਸਨ। ਇਸ ਲਈ ਮਾਣਕ ਨੂੰ ਸੰਗੀਤ ਦੀ ਗੁੜ੍ਹਤੀ ਵਿਰਾਸਤ ਵਿੱਚ ਹੀ ਮਿਲੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('3bc23f8c-a6eb-46d1-b1b5-060726ff536c', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਾਣਕ ਦਾ ਅਸਲ ਨਾਮ ਲਤੀਫ ਮੁਹੰਮਦ ਸੀ। ਪਿੰਡ ਵਿੱਚ ਇਸਨੂੰ ਲਾਡ ਨਾਲ 'ਲੱਧਾ' ਕਹਿ ਕੇ ਬੁਲਾਇਆ ਜਾਂਦਾ ਸੀ। ਘਰ ਵਿੱਚ ਭਾਵੇਂ ਗਰੀਬੀ ਸੀ ਪਰ ਮਾਣਕ ਅੰਦਰ ਬੈਠਾ ਕਲਾਕਾਰ ਗਰੀਬੀ ਦੀ ਕੰਧ ਨੂੰ ਢਾਹੁਣ ਲਈ ਕਾਹਲਾ ਸੀ। ਸਕੂਲ ਪੜ੍ਹਦਿਆਂ ਅਧਿਆਪਕਾਂ ਨੇ 'ਬਾਲ-ਸਭਾ' ਵਿੱਚ ਮਾਣਕ ਨੂੰ ਐਸਾ ਮੌਕਾ ਦਿੱਤਾ ਕਿ ਉਸਨੇ ਮੁੜ ਪਿੱਛੇ ਮੁੜ ਕੇ ਨਾ ਦੇਖਿਆ। ਅਧਿਆਪਕਾਂ ਦੀ ਹੱਲਾਸ਼ੇਰੀ ਨੇ ਉਸ ਅੰਦਰ ਕੁਝ ਵੱਖਰਾ ਤੇ ਵੱਡਾ ਕਰ ਗੁਜ਼ਰਨ ਦੀ ਚਿਣਗ ਲਾ ਦਿੱਤੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('5e2bdf22-b720-46ad-8e6b-d454d8058dea', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਹ ਚਿਣਗ ਉਸਨੂੰ ਉਸਤਾਦ ਖੁਸ਼ੀ ਮੁਹੰਮਦ ਕੱਵਾਲ ਦੇ ਡੇਰੇ ਉੱਤੇ ਲੈ ਆਈ ਅਤੇ ਉਹ ਉਸਦਾ ਬੁਲੰਦ ਸ਼ਾਗਿਰਦ ਬਣਿਆ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('763b67ab-6f63-4f8c-a3a6-3bb9ff12cc18', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕੁਲਦੀਪ ਮਾਣਕ ਦਾ ਜਨਮ ਬਠਿੰਡਾ ਜ਼ਿਲ੍ਹੇ ਦੇ ਪਿੰਡ ਜਲਾਲ ਵਿਖੇ 11 ਨਵੰਬਰ, 1949 ਈ: ਨੂੰ ਪਿਤਾ ਨਿੱਕਾ ਖਾਨ ਅਤੇ ਮਾਤਾ ਬਚਨੋ ਦੇ ਘਰ ਹੋਇਆ। 1968 ਈ: ਵਿੱਚ ਮਾਣਕ ਦਾ ਵਿਆਹ ਸਰਬਜੀਤ ਕੌਰ ਨਾਲ ਹੋਇਆ। ਇਹਨਾਂ ਦੇ ਘਰ ਪੁੱਤਰ ਯੁੱਧਵੀਰ ਮਾਣਕ ਅਤੇ ਧੀ ਸ਼ਕਤੀ ਮਾਣਕ ਨੇ ਜਨਮ ਲਿਆ। ਇਹਨਾਂ ਦਾ ਪਰਿਵਾਰ ਪੀੜ੍ਹੀ ਦਰ ਪੀੜ੍ਹੀ ਸੰਗੀਤ ਨਾਲ ਜੁੜਿਆ ਹੋਇਆ ਸੀ। ਪਿੰਡ ਵਿੱਚ ਇਹਨਾਂ ਦਾ ਪਰਿਵਾਰ 'ਮਰਦਾਨੇ ਕਾ' ਵਜੋਂ ਜਾਣਿਆ ਜਾਂਦਾ ਹੈ। ਇਹਨਾਂ ਦੇ ਪੁਰਖੇ ਨਾਭਾ ਰਿਆਸਤ ਦੇ ਰਾਜੇ ਹੀਰਾ ਸਿੰਘ ਦੇ ਦਰਬਾਰ ਵਿੱਚ ਹਜ਼ੂਰੀ ਰਾਗੀ ਵਜੋਂ ਸੇਵਾ ਨਿਭਾਉਂਦੇ ਰਹੇ ਸਨ। ਇਸ ਲਈ ਮਾਣਕ ਨੂੰ ਸੰਗੀਤ ਦੀ ਗੁੜ੍ਹਤੀ ਵਿਰਾਸਤ ਵਿੱਚ ਹੀ ਮਿਲੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('cb68e30e-370a-44d1-a534-99c333cf74b0', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਘਰ ਵਿੱਚ ਭਾਵੇਂ ਗਰੀਬੀ ਸੀ ਪਰ ਮਾਣਕ ਅੰਦਰ ਬੈਠਾ ਕਲਾਕਾਰ ਗਰੀਬੀ ਦੀ ਕੰਧ ਨੂੰ ਢਾਹੁਣ ਲਈ ਕਾਹਲਾ ਸੀ। ਸਕੂਲ ਪੜ੍ਹਦਿਆਂ ਅਧਿਆਪਕਾਂ ਨੇ 'ਬਾਲ-ਸਭਾ' ਵਿੱਚ ਮਾਣਕ ਨੂੰ ਐਸਾ ਮੌਕਾ ਦਿੱਤਾ ਕਿ ਉਸਨੇ ਮੁੜ ਪਿੱਛੇ ਮੁੜ ਕੇ ਨਾ ਦੇਖਿਆ। ਅਧਿਆਪਕਾਂ ਦੀ ਹੱਲਾਸ਼ੇਰੀ ਨੇ ਉਸ ਅੰਦਰ ਕੁਝ ਵੱਖਰਾ ਤੇ ਵੱਡਾ ਕਰ ਗੁਜ਼ਰਨ ਦੀ ਚਿਣਗ ਲਾ ਦਿੱਤੀ। ਇਹ ਚਿਣਗ ਉਸਨੂੰ ਉਸਤਾਦ ਖੁਸ਼ੀ ਮੁਹੰਮਦ ਕੱਵਾਲ ਦੇ ਡੇਰੇ ਉੱਤੇ ਲੈ ਆਈ ਅਤੇ ਉਹ ਉਸਦਾ ਬੁਲੰਦ ਸ਼ਾਗਿਰਦ ਬਣਿਆ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('6c7129a7-cff2-4664-9d3d-82c930aa328d', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪੰਜਾਬ ਦੀ ਧਰਤੀ ਨੇ ਕਈ ਪ੍ਰਸਿੱਧ ਲੋਕ-ਗਾਇਕਾਂ ਨੂੰ ਜਨਮ ਦਿੱਤਾ ਹੈ। ਇਹਨਾਂ ਗਾਇਕਾਂ ਨੇ ਗੀਤ-ਸੰਗੀਤ ਦੇ ਖੇਤਰ ਵਿੱਚ ਆਪਣੀ ਬੁਲੰਦ ਆਵਾਜ਼ ਨਾਲ ਸਫਲਤਾ ਦੇ ਝੰਡੇ ਗੱਡੇ ਹਨ। ਗਾਇਕ ਲਾਲ ਚੰਦ ਯਮਲਾ ਜੱਟ, ਪ੍ਰਕਾਸ਼ ਕੌਰ ਅਤੇ ਸੁਰਿੰਦਰ ਕੌਰ ਭੈਣਾਂ, ਆਸਾ ਸਿੰਘ ਮਸਤਾਨਾ, ਗੁਰਦਾਸ ਮਾਨ ਆਦਿ ਕਲਾਕਾਰਾਂ ਨੇ ਪੰਜਾਬੀ ਗੀਤਾਂ ਨੂੰ ਸੰਸਾਰ ਦੇ ਕੋਨੇ-ਕੋਨੇ ਤੀਕ ਪਹੁੰਚਾਇਆ ਹੈ। ਇਹਨਾਂ ਸਿਰਕੱਢ ਨਾਵਾਂ ਵਿੱਚੋਂ ਹੀ ਇੱਕ ਨਾਮ ਹੈ - ਕੁਲਦੀਪ ਮਾਣਕ। ਜਿਵੇਂ ਸੁਰਿੰਦਰ ਕੌਰ ਨੂੰ ਸਾਰੇ 'ਪੰਜਾਬ ਦੀ ਕੋਇਲ' ਵਜੋਂ ਜਾਣਦੇ ਹਨ, ਉਵੇਂ ਹੀ ਕੁਲਦੀਪ ਮਾਣਕ ਨੂੰ ਪੰਜਾਬੀ 'ਕਲੀਆਂ ਦਾ ਬਾਦਸ਼ਾਹ' ਵਜੋਂ ਜਾਣਦੇ ਹਨ। ਕਲੀ ਪੰਜਾਬੀ ਕਵਿਤਾ ਦਾ ਇੱਕ ਮਸ਼ਹੂਰ ਛੰਦ ਹੈ। ਮਾਣਕ ਦੀ ਪ੍ਰਸਿੱਧੀ ਕਲੀਆਂ ਗਾਉਣ ਕਰਕੇ ਹੀ ਜ਼ਿਆਦਾ ਹੋਈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('cc02c57f-fb72-4556-9dd9-31cceda73a37', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਾਣਕ ਦਾ ਅਸਲ ਨਾਮ ਲਤੀਫ ਮੁਹੰਮਦ ਸੀ। ਪਿੰਡ ਵਿੱਚ ਇਸਨੂੰ ਲਾਡ ਨਾਲ 'ਲੱਧਾ' ਕਹਿ ਕੇ ਬੁਲਾਇਆ ਜਾਂਦਾ ਸੀ। ਘਰ ਵਿੱਚ ਭਾਵੇਂ ਗਰੀਬੀ ਸੀ ਪਰ ਮਾਣਕ ਅੰਦਰ ਬੈਠਾ ਕਲਾਕਾਰ ਗਰੀਬੀ ਦੀ ਕੰਧ ਨੂੰ ਢਾਹੁਣ ਲਈ ਕਾਹਲਾ ਸੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
