  ('45abad7b-50c6-4dbb-899f-df015796956c', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪੰਜਾਬ ਦੀ ਧਰਤੀ ਨੇ ਕਈ ਪ੍ਰਸਿੱਧ ਲੋਕ-ਗਾਇਕਾਂ ਨੂੰ ਜਨਮ ਦਿੱਤਾ ਹੈ। ਇਹਨਾਂ ਗਾਇਕਾਂ ਨੇ ਗੀਤ-ਸੰਗੀਤ ਦੇ ਖੇਤਰ ਵਿੱਚ ਆਪਣੀ ਬੁਲੰਦ ਆਵਾਜ਼ ਨਾਲ ਸਫਲਤਾ ਦੇ ਝੰਡੇ ਗੱਡੇ ਹਨ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('a067e2db-91e3-4c06-8dac-76900b566168', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਗਾਇਕ ਲਾਲ ਚੰਦ ਯਮਲਾ ਜੱਟ, ਪ੍ਰਕਾਸ਼ ਕੌਰ ਅਤੇ ਸੁਰਿੰਦਰ ਕੌਰ ਭੈਣਾਂ, ਆਸਾ ਸਿੰਘ ਮਸਤਾਨਾ, ਗੁਰਦਾਸ ਮਾਨ ਆਦਿ ਕਲਾਕਾਰਾਂ ਨੇ ਪੰਜਾਬੀ ਗੀਤਾਂ ਨੂੰ ਸੰਸਾਰ ਦੇ ਕੋਨੇ-ਕੋਨੇ ਤੀਕ ਪਹੁੰਚਾਇਆ ਹੈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('3abf6d00-ef8c-42ae-9d2a-25b4a77f511c', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਜਿਵੇਂ ਸੁਰਿੰਦਰ ਕੌਰ ਨੂੰ ਸਾਰੇ 'ਪੰਜਾਬ ਦੀ ਕੋਇਲ' ਵਜੋਂ ਜਾਣਦੇ ਹਨ, ਉਵੇਂ ਹੀ ਕੁਲਦੀਪ ਮਾਣਕ ਨੂੰ ਪੰਜਾਬੀ 'ਕਲੀਆਂ ਦਾ ਬਾਦਸ਼ਾਹ' ਵਜੋਂ ਜਾਣਦੇ ਹਨ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('480fdc70-51d8-488b-bb94-3c717cac265f', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕੁਲਦੀਪ ਮਾਣਕ ਦਾ ਜਨਮ ਬਠਿੰਡਾ ਜ਼ਿਲ੍ਹੇ ਦੇ ਪਿੰਡ ਜਲਾਲ ਵਿਖੇ 11 ਨਵੰਬਰ, 1949 ਈ: ਨੂੰ ਪਿਤਾ ਨਿੱਕਾ ਖਾਨ ਅਤੇ ਮਾਤਾ ਬਚਨੋ ਦੇ ਘਰ ਹੋਇਆ। ਮਾਣਕ ਦਾ ਅਸਲ ਨਾਮ ਲਤੀਫ ਮੁਹੰਮਦ ਸੀ। ਪਿੰਡ ਵਿੱਚ ਇਸਨੂੰ ਲਾਡ ਨਾਲ 'ਲੱਧਾ' ਕਹਿ ਕੇ ਬੁਲਾਇਆ ਜਾਂਦਾ ਸੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('83f04e05-7c86-4dd0-ac71-2ad8647f92d0', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਹਨਾਂ ਦਾ ਪਰਿਵਾਰ ਪੀੜ੍ਹੀ ਦਰ ਪੀੜ੍ਹੀ ਸੰਗੀਤ ਨਾਲ ਜੁੜਿਆ ਹੋਇਆ ਸੀ। ਪਿੰਡ ਵਿੱਚ ਇਹਨਾਂ ਦਾ ਪਰਿਵਾਰ 'ਮਰਦਾਨੇ ਕਾ' ਵਜੋਂ ਜਾਣਿਆ ਜਾਂਦਾ ਹੈ। ਇਹਨਾਂ ਦੇ ਪੁਰਖੇ ਨਾਭਾ ਰਿਆਸਤ ਦੇ ਰਾਜੇ ਹੀਰਾ ਸਿੰਘ ਦੇ ਦਰਬਾਰ ਵਿੱਚ ਹਜ਼ੂਰੀ ਰਾਗੀ ਵਜੋਂ ਸੇਵਾ ਨਿਭਾਉਂਦੇ ਰਹੇ ਸਨ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('c144d14a-4845-44fe-a7ae-fda54ad8812a', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਘਰ ਵਿੱਚ ਭਾਵੇਂ ਗਰੀਬੀ ਸੀ ਪਰ ਮਾਣਕ ਅੰਦਰ ਬੈਠਾ ਕਲਾਕਾਰ ਗਰੀਬੀ ਦੀ ਕੰਧ ਨੂੰ ਢਾਹੁਣ ਲਈ ਕਾਹਲਾ ਸੀ। ਸਕੂਲ ਪੜ੍ਹਦਿਆਂ ਅਧਿਆਪਕਾਂ ਨੇ 'ਬਾਲ-ਸਭਾ' ਵਿੱਚ ਮਾਣਕ ਨੂੰ ਐਸਾ ਮੌਕਾ ਦਿੱਤਾ ਕਿ ਉਸਨੇ ਮੁੜ ਪਿੱਛੇ ਮੁੜ ਕੇ ਨਾ ਦੇਖਿਆ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('2308235c-ab2c-4672-a3fa-4e849acf328e', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਅਧਿਆਪਕਾਂ ਦੀ ਹੱਲਾਸ਼ੇਰੀ ਨੇ ਉਸ ਅੰਦਰ ਕੁਝ ਵੱਖਰਾ ਤੇ ਵੱਡਾ ਕਰ ਗੁਜ਼ਰਨ ਦੀ ਚਿਣਗ ਲਾ ਦਿੱਤੀ। ਇਹ ਚਿਣਗ ਉਸਨੂੰ ਉਸਤਾਦ ਖੁਸ਼ੀ ਮੁਹੰਮਦ ਕੱਵਾਲ ਦੇ ਡੇਰੇ ਉੱਤੇ ਲੈ ਆਈ ਅਤੇ ਉਹ ਉਸਦਾ ਬੁਲੰਦ ਸ਼ਾਗਿਰਦ ਬਣਿਆ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('a09a0bf1-4e15-4aa3-9114-524c0ffc80cc', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕੁਲਦੀਪ ਮਾਣਕ ਦਾ ਜਨਮ ਬਠਿੰਡਾ ਜ਼ਿਲ੍ਹੇ ਦੇ ਪਿੰਡ ਜਲਾਲ ਵਿਖੇ 11 ਨਵੰਬਰ, 1949 ਈ: ਨੂੰ ਪਿਤਾ ਨਿੱਕਾ ਖਾਨ ਅਤੇ ਮਾਤਾ ਬਚਨੋ ਦੇ ਘਰ ਹੋਇਆ। 1968 ਈ: ਵਿੱਚ ਮਾਣਕ ਦਾ ਵਿਆਹ ਸਰਬਜੀਤ ਕੌਰ ਨਾਲ ਹੋਇਆ। ਇਹਨਾਂ ਦੇ ਘਰ ਪੁੱਤਰ ਯੁੱਧਵੀਰ ਮਾਣਕ ਅਤੇ ਧੀ ਸ਼ਕਤੀ ਮਾਣਕ ਨੇ ਜਨਮ ਲਿਆ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('eaa1bd89-8f3b-44d9-9edc-abe1169493ab', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਾਣਕ ਦਾ ਅਸਲ ਨਾਮ ਲਤੀਫ ਮੁਹੰਮਦ ਸੀ। ਪਿੰਡ ਵਿੱਚ ਇਸਨੂੰ ਲਾਡ ਨਾਲ 'ਲੱਧਾ' ਕਹਿ ਕੇ ਬੁਲਾਇਆ ਜਾਂਦਾ ਸੀ। ਘਰ ਵਿੱਚ ਭਾਵੇਂ ਗਰੀਬੀ ਸੀ ਪਰ ਮਾਣਕ ਅੰਦਰ ਬੈਠਾ ਕਲਾਕਾਰ ਗਰੀਬੀ ਦੀ ਕੰਧ ਨੂੰ ਢਾਹੁਣ ਲਈ ਕਾਹਲਾ ਸੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('da773811-b4e6-4a18-a120-f244d80c26c0', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪੰਜਾਬ ਦੀ ਧਰਤੀ ਨੇ ਕਈ ਪ੍ਰਸਿੱਧ ਲੋਕ-ਗਾਇਕਾਂ ਨੂੰ ਜਨਮ ਦਿੱਤਾ ਹੈ। ਇਹਨਾਂ ਗਾਇਕਾਂ ਨੇ ਗੀਤ-ਸੰਗੀਤ ਦੇ ਖੇਤਰ ਵਿੱਚ ਆਪਣੀ ਬੁਲੰਦ ਆਵਾਜ਼ ਨਾਲ ਸਫਲਤਾ ਦੇ ਝੰਡੇ ਗੱਡੇ ਹਨ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('eea32b27-ae5c-44a0-890c-bc936b386b45', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਈ ਸਾਲਾਂ ਚੀ ਸਖ਼ਤ ਸੰਗੀਤ ਸਾਧਨਾ ਨੇ ਆਪਣਾ ਰੰਗ ਦਿਖਾਉਣਾ ਸ਼ੁਰੂ ਕਰ ਦਿੱਤਾ। ਉਸਤਾਦ ਦੀਆਂ ਝਿੜਕਾਂ ਉਸਨੂੰ ਘਿਓ ਵਾਂਗ ਲੱਗਦੀਆਂ। ਉਸ ਨੇ ਬਹੁਤ ਸ਼ਿੱਦਤ ਨਾਲ ਰਾਗਦਾਰੀ ਦੀਆਂ ਬਰੀਕੀਆਂ ਸਿੱਖਣੀਆਂ ਸ਼ੁਰੂ ਕਰ ਦਿੱਤੀਆਂ। ਉਸ ਦੀ ਅਵਾਜ਼ ਵਿੱਚ ਲੋਹੇ ਦੀ ਬੁਲੰਦੀ ਸੀ। ਜਦੋਂ ਉਹ ਇੱਕ ਹੱਥ ਕੰਨ ਉੱਤੇ ਰੱਖ ਕੇ ਹੇਕ ਲਾਉਂਦਾ ਤਾਂ ਸੁਣਨ ਵਾਲਿਆਂ ਦੀਆਂ ਅੱਖਾਂ ਟੱਡੀਆਂ ਰਹਿ ਜਾਂਦੀਆਂ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('fa30ea6e-0759-4023-b209-655b0aafb656', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹੁਣ ਮਾਣਕ ਆਪਣੀ ਮਿੱਥੀ ਮੰਜ਼ਲ ਵੱਲ ਹੋ ਤੁਰਿਆ। ਉਸ ਨੇ ਬਠਿੰਡਾ ਛੱਡ ਕੇ ਲੁਧਿਆਣੇ ਨੂੰ ਆਪਣਾ ਘਰ ਬਣਾ ਲਿਆ। ਉਹ ਹਰਚਰਨ ਗਰੇਵਾਲ ਤੇ ਸੀਮਾ ਨਾਲ ਸਟੇਜਾਂ ਲਾਉਣ ਲੱਗਿਆ। 1968 ਵਿੱਚ ਉਸ ਦਾ ਪਹਿਲਾ ਦੋਗਾਣਾ ਰਿਕਾਰਡ ਹੋਇਆ। ਉਸ ਸਮੇਂ ਭਾਵੇਂ ਦੋਗਾਣਾ ਗਾਇਕੀ ਦਾ ਬੋਲਬਾਲਾ ਸੀ ਪਰ ਮਾਣਕ ਨੇ ਸੋਲੋ ਗੀਤ ਗਾਉਣੇ ਸ਼ੁਰੂ ਕਰ ਦਿੱਤੇ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('ba16c394-4479-4cf2-ae99-7764960558b9', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਛਾਂਟਵਾਂ ਸਰੀਰ, ਮਧਰਾ ਕੱਦ ਤੇ ਬੁਲੰਦ ਅਵਾਜ਼ ਉਸਨੂੰ ਵਿਲੱਖਣ ਪਛਾਣ ਬਖਸ਼ਦੇ। ਉਹ ਮਾਈਕ ਤੋਂ ਦੂਰ ਖੜ੍ਹ ਕੇ ਗਾਉਂਦਾ ਪਰ ਮਜ਼ਾਲ ਹੈ ਸਰੋਤਿਆਂ ਤੱਕ ਅਵਾਜ਼ ਜਾਣ ਵਿੱਚ ਕੋਈ ਗੜਬੜ ਹੋਵੇ। ਇਸੇ ਦੌਰਾਨ ਉਸਦੀ ਮੁਲਾਕਾਤ ਗੀਤਕਾਰ ਹਰਦੇਵ ਦਿਲਗੀਰ (ਦੇਵ ਥਰੀਕਿਆਂ ਵਾਲਾ) ਨਾਲ ਹੋਈ। ਦੇਵ ਦੀ ਮਾਣਕ ਦੇ ਪਿੰਡ ਜਲਾਲ ਵਿਖੇ ਰਿਸ਼ਤੇਦਾਰੀ ਹੋਣ ਕਰਕੇ ਛੇਤੀ ਹੀ ਉਹ ਚੰਗੇ ਲਿਹਾਜ਼ੀ ਬਣ ਗਏ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('44895f71-b60d-4ac9-8182-86ee90db37c0', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦੇਵ ਥਰੀਕਿਆਂ ਵਾਲੇ ਨੇ ਮਾਣਕ ਲਈ ਕਲੀਆਂ ਤੇ ਲੋਕ-ਗਾਥਾਵਾਂ ਲਿਖੀਆਂ। ਮਾਣਕ ਦੀ ਅਵਾਜ਼ ਵਿੱਚ ਰਿਕਾਰਡ ਹੋਈ ਕਲੀ 'ਤੇਰੇ ਟਿੱਲੇ ਤੋਂ ਅਹੁ ਸੂਰਤ ਦੀਹਦੀ ਆ ਹੀਰ ਦੀ' ਨੇ ਉਸ ਨੂੰ ਰਾਤੋ-ਰਾਤ ਸ਼ੁਹਰਤ ਦੇ ਅਸਮਾਨ ਉੱਤੇ ਪਹੁੰਚਾ ਦਿੱਤਾ। ਇਸ ਕਲੀ ਸਦਕਾ ਉਸ ਨੂੰ 'ਕਲੀਆਂ ਦਾ ਬਾਦਸ਼ਾਹ' ਦਾ ਖਿਤਾਬ ਮਿਲਿਆ। ਉਸ ਨੇ ਭਾਵੇਂ ਗਿਣਤੀ ਦੀਆਂ ਕਲੀਆਂ ਹੀ ਗਾਈਆਂ ਪਰ ਉਸ ਦੀ ਪ੍ਰਸਿੱਧੀ ਕਲੀਆਂ ਗਾਉਣ ਕਰਕੇ ਹੀ ਜ਼ਿਆਦਾ ਹੋਈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('9908581a-0fd2-4a1f-a6bd-8315037190d9', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਾਣਕ ਦੇ 'ਮਾਣਕ' ਬਣਨ ਦਾ ਕਿੱਸਾ ਵੀ ਬੜਾ ਦਿਲਚਸਪ ਹੈ। ਇੱਕ ਵਿਆਹ ਵਿੱਚ ਉਸ ਨੇ ਉਸ ਸਮੇਂ ਦੇ ਮੁੱਖ-ਮੰਤਰੀ ਸ. ਪ੍ਰਤਾਪ ਸਿੰਘ ਕੈਰੋਂ ਦੀ ਹਾਜ਼ਰੀ ਵਿੱਚ 'ਸਿਹਰਾ' ਗਾਇਆ। ਉਸ ਦੀ ਅਵਾਜ਼ ਸੁਣ ਕੇ ਕੈਰੋਂ ਸਾਹਿਬ ਨੇ ਕਿਹਾ ਕਿ ਇਹ ਮੁੰਡਾ ਤਾਂ ਮਾਣਕ ਐ, ਮਾਣਕ! ਇਸ ਤੋਂ ਉਸ ਨੇ ਹਮੇਸ਼ਾ ਲਈ ਆਪਣੇ ਨਾਂ ਨਾਲ ਮਾਣਕ ਜੋੜ ਲਿਆ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('17a34949-753e-4165-9d16-291c0d017b30', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਾਣਕ ਦਾ ਯੁੱਗ ਕੈਸਟਾਂ ਦਾ ਯੁੱਗ ਸੀ। ਮੋਟਰ-ਕਾਰਾਂ ਅਤੇ ਟਰੈਕਟਰਾਂ ਉੱਤੇ ਟੇਪਾਂ ਵਿੱਚ ਕੈਸਟਾਂ ਹੀ ਮਨੋਰੰਜਨ ਕਰਦੀਆਂ ਸਨ। ਮਾਣਕ ਨੇ ਬਹੁਤ ਸਾਰੇ ਗੀਤਕਾਰਾਂ ਦੇ ਗੀਤ ਗਾਏ ਪਰ ਸਭ ਤੋਂ ਵੱਧ ਗੀਤ ਦੇਵ ਥਰੀਕਿਆਂ ਵਾਲੇ ਦੇ ਹੀ ਸਨ। ਬਾਬਾ ਬੰਦਾ ਸਿੰਘ ਬਹਾਦਰ ਦੀ ਵਾਰ 'ਲੈ ਕੇ ਕਲਗੀਧਰ ਤੋਂ ਥਾਪੜਾ' ਨੂੰ ਜਦੋਂ ਉਹ ਰੂਹ ਨਾਲ ਗਾਉਂਦਾ ਤਾਂ ਲੋਕ ਅਸ਼-ਅਸ਼ ਕਰ ਉੱਠਦੇ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('bcab8b63-5082-4d67-9361-8d401cb45706', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਸ ਦੇ ਪੁਰਖੇ ਗੁਰਬਾਣੀ ਸੰਗੀਤ ਨਾਲ ਜੁੜੇ ਹੋਣ ਕਰਕੇ ਉਸ ਅੰਦਰ ਮਹਾਨ ਸਿੱਖ ਵਿਰਾਸਤ ਲਈ ਅਥਾਹ ਸਤਿਕਾਰ ਪਿਆ ਸੀ। ਉਸ ਨੇ ਸਿੱਖੀ ਲਈ ਸ਼ਹੀਦੀਆਂ ਦੇਣ ਵਾਲੇ ਯੋਧਿਆਂ ਦੀ ਸ਼ਾਨ ਵਿੱਚ ਵੀ ਬਹੁਤ ਗਾਇਆ। 'ਭਾਈ ਮਤੀ ਦਾਸ ਗੁਰੂ ਦਾ ਪਿਆਰਾ, ਮੁੱਖ ਸਤਿਨਾਮ ਬੋਲਦਾ, ਆ ਜੋ ਜੀਹਨੇ ਨੱਚਣਾ ਖੰਡੇ ਦੀ ਧਾਰ ਉੱਤੇ' ਸਮੇਤ ਕਈ ਦਰਜਨ ਧਾਰਮਿਕ ਗੀਤ ਗਾਏ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('c8bfbd5e-fb48-4fe5-abee-811a76bbbd8e', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਾਣਕ ਨੇ ਸਮਾਜਿਕ ਸਰੋਕਾਰਾਂ ਨਾਲ ਲਬਰੇਜ਼ ਗੀਤ ਵੀ ਆਪਣੀ ਗਾਇਕੀ ਦਾ ਸ਼ਿੰਗਾਰ ਬਣਾਏ, ÒÒਮੈਂ ਹੁੰਦੀ ਐਂ ਮੈਂ ਤੂੰ ਦੁਨੀਆਂ ਵਾਙੂੰ, ਛੇਤੀ ਹੋਇਆ ਕੀ ਜੇ ਧੀ ਜੰਮ ਪਈ, ਤੇਰੀ ਕੁੱਖ ਤਾਂ ਸੁਲੱਖਣੀ ਹੋਈ, ਛੇਤੀ ਕਰ ਸਰਵਣ ਪੁੱਤਰਾਂ ਪਾਣੀ ਪਿਆ ਦੇ ਤੂੰ।ÓÓ$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('4d303b5e-ce25-4e04-906a-bae03723794e', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਸ ਦਾ ਗਾਇਆ Òਮੈਂ ਚਾਦਰ ਕੱਢਦੀ ਨੀ, ਗਿਣ ਤੋਪੇ ਪਾਵਾਂ...Ó ਨੇ ਲੰਮਾ ਸਮਾਂ ਰੇਡੀਓ ਉੱਤੇ ਸਰਦਾਰੀ ਕੀਤੀ ਹੈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('74e2b06a-dbf3-467e-801c-5bfa87fb950e', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਾਣਕ ਨੇ ਭਾਰਤ ਵਿੱਚ ਹੀ ਨਹੀਂ ਬਲਕਿ ਵਿਦੇਸ਼ਾਂ ਵਿੱਚ ਵੀ ਬਹੁਤ ਸਾਰੇ ਕਾਮਯਾਬ ਅਖਾੜੇ ਲਾ ਕੇ ਆਪਣੀ ਕਲਾ ਦਾ ਲੋਹਾ ਮਨਵਾਇਆ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('e0a4144c-d3db-4737-8a4f-eb493f780f59', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਸ ਦੀਆਂ ਅਣਗਿਣਤ ਪੁਰਾਣੀਆਂ ਵੀਡੀਓਜ਼ ਅੱਜ-ਕੱਲ੍ਹ ਸੋਸ਼ਲ-ਮੀਡੀਆ ਉੱਤੇ ਵੀ ਵੇਖਣ ਨੂੰ ਮਿਲ ਜਾਂਦੀਆਂ ਹਨ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('467bcdd8-6ae6-4403-ba12-ba57ed5b6622', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਾਣਕ ਸੁਭਾਅ ਪੱਖੋਂ ਸਰਲ ਪਰ ਹਾਜ਼ਰ-ਜਵਾਬ ਸੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('2b795b80-7a57-4220-94c1-b374415d1d2e', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਸ ਨੇ ਆਪਣੀ ਕਲਾ ਨੂੰ ਮਹਿਜ਼ ਆਪਣੇ ਖੀਸੇ ਭਰਨ ਤੱਕ ਸੀਮਤ ਨਹੀਂ ਰੱਖਿਆ। ਉਸ ਲਈ ਮੋਹ-ਮੁਹੱਬਤ ਬਹੁਤ ਵੱਡੀ ਚੀਜ਼ ਸੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
