  ('973fdbc6-9ea0-48fb-8a69-8dc62050cef1', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕੁਝ ਸਮਾਂ ਬਿਮਾਰ ਰਹਿਣ ਮਗਰੋਂ ਅੰਤ 26, ਨਵੰਬਰ 2001 ਨੂੰ ਪੰਜਾਬ ਦੀ ਇਹ ਬੁਲੰਦ ਆਵਾਜ਼ ਹਮੇਸ਼ਾ ਲਈ ਖ਼ਾਮੋਸ਼ ਹੋ ਗਈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('201100d2-6b4f-4010-8814-a700ef95e40f', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪ੍ਰਸਿੱਧ ਲੋਕ-ਗਾਇਕਾਂ ਬਾਰੇ ਜਾਣਕਾਰੀ ਵਿੱਚ ਵਾਧਾ। ਆਪਣੀ ਵਿਰਾਸਤੀ ਕਲਾ ਵਿੱਚ ਰੁਚੀ ਜਾਗ੍ਰਿਤ ਹੋਣੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('d24616f8-008d-4276-8b8d-0a81d3d42ea3', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪੰਜਾਬ ਦੀ ਧਰਤੀ ਨੇ ਕਈ ਪ੍ਰਸਿੱਧ ਲੋਕ-ਗਾਇਕਾਂ ਨੂੰ ਜਨਮ ਦਿੱਤਾ ਹੈ। ਇਹਨਾਂ ਗਾਇਕਾਂ ਨੇ ਗੀਤ-ਸੰਗੀਤ ਦੇ ਖੇਤਰ ਵਿੱਚ ਆਪਣੀ ਬੁਲੰਦ ਆਵਾਜ਼ ਨਾਲ ਸਫਲਤਾ ਦੇ ਝੰਡੇ ਗੱਡੇ ਹਨ। ਗਾਇਕ ਲਾਲ ਚੰਦ ਯਮਲਾ ਜੱਟ, ਪ੍ਰਕਾਸ਼ ਕੌਰ ਅਤੇ ਸੁਰਿੰਦਰ ਕੌਰ ਭੈਣਾਂ, ਆਸਾ ਸਿੰਘ ਮਸਤਾਨਾ, ਗੁਰਦਾਸ ਮਾਨ ਆਦਿ ਕਲਾਕਾਰਾਂ ਨੇ ਪੰਜਾਬੀ ਗੀਤਾਂ ਨੂੰ ਸੰਸਾਰ ਦੇ ਕੋਨੇ-ਕੋਨੇ ਤੀਕ ਪਹੁੰਚਾਇਆ ਹੈ। ਇਹਨਾਂ ਸਿਰਕੱਢ ਨਾਵਾਂ ਵਿੱਚੋਂ ਹੀ ਇੱਕ ਨਾਮ ਹੈ - ਕੁਲਦੀਪ ਮਾਣਕ। ਜਿਵੇਂ ਸੁਰਿੰਦਰ ਕੌਰ ਨੂੰ ਸਾਰੇ 'ਪੰਜਾਬ ਦੀ ਕੋਇਲ' ਵਜੋਂ ਜਾਣਦੇ ਹਨ, ਉਵੇਂ ਹੀ ਕੁਲਦੀਪ ਮਾਣਕ ਨੂੰ ਪੰਜਾਬੀ 'ਕਲੀਆਂ ਦਾ ਬਾਦਸ਼ਾਹ' ਵਜੋਂ ਜਾਣਦੇ ਹਨ। ਕਲੀ ਪੰਜਾਬੀ ਕਵਿਤਾ ਦਾ ਇੱਕ ਮਸ਼ਹੂਰ ਛੰਦ ਹੈ। ਮਾਣਕ ਦੀ ਪ੍ਰਸਿੱਧੀ ਕਲੀਆਂ ਗਾਉਣ ਕਰਕੇ ਹੀ ਜ਼ਿਆਦਾ ਹੋਈ। ਮਾਣਕ ਦਾ ਜਨਮ ਬਠਿੰਡਾ ਜ਼ਿਲ੍ਹੇ ਦੇ ਪਿੰਡ ਜਲਾਲ ਵਿਖੇ 11 ਨਵੰਬਰ, 1949 ਈ: ਨੂੰ ਪਿਤਾ ਨਿੱਕਾ ਖਾਨ ਅਤੇ ਮਾਤਾ ਬਚਨੋ ਦੇ ਘਰ ਹੋਇਆ। 1968 ਈ: ਵਿੱਚ ਮਾਣਕ ਦਾ ਵਿਆਹ ਸਰਬਜੀਤ ਕੌਰ ਨਾਲ ਹੋਇਆ। ਇਹਨਾਂ ਦੇ ਘਰ ਪੁੱਤਰ ਯੁੱਧਵੀਰ ਮਾਣਕ ਅਤੇ ਧੀ ਸ਼ਕਤੀ ਮਾਣਕ ਨੇ ਜਨਮ ਲਿਆ। ਇਹਨਾਂ ਦਾ ਪਰਿਵਾਰ ਪੀੜ੍ਹੀ ਦਰ ਪੀੜ੍ਹੀ ਸੰਗੀਤ ਨਾਲ ਜੁੜਿਆ ਹੋਇਆ ਸੀ। ਪਿੰਡ ਵਿੱਚ ਇਹਨਾਂ ਦਾ ਪਰਿਵਾਰ 'ਮਰਦਾਨੇ ਕਾ' ਵਜੋਂ ਜਾਣਿਆ ਜਾਂਦਾ ਹੈ। ਇਹਨਾਂ ਦੇ ਪੁਰਖੇ ਨਾਭਾ ਰਿਆਸਤ ਦੇ ਰਾਜੇ ਹੀਰਾ ਸਿੰਘ ਦੇ ਦਰਬਾਰ ਵਿੱਚ ਹਜ਼ੂਰੀ ਰਾਗੀ ਵਜੋਂ ਸੇਵਾ ਨਿਭਾਉਂਦੇ ਰਹੇ ਸਨ। ਇਸ ਲਈ ਮਾਣਕ ਨੂੰ ਸੰਗੀਤ ਦੀ ਗੁੜ੍ਹਤੀ ਵਿਰਾਸਤ ਵਿੱਚ ਹੀ ਮਿਲੀ। ਮਾਣਕ ਦਾ ਅਸਲ ਨਾਮ ਲਤੀਫ ਮੁਹੰਮਦ ਸੀ। ਪਿੰਡ ਵਿੱਚ ਇਸਨੂੰ ਲਾਡ ਨਾਲ 'ਲੱਧਾ' ਕਹਿ ਕੇ ਬੁਲਾਇਆ ਜਾਂਦਾ ਸੀ। ਘਰ ਵਿੱਚ ਭਾਵੇਂ ਗਰੀਬੀ ਸੀ ਪਰ ਮਾਣਕ ਅੰਦਰ ਬੈਠਾ ਕਲਾਕਾਰ ਗਰੀਬੀ ਦੀ ਕੰਧ ਨੂੰ ਢਾਹੁਣ ਲਈ ਕਾਹਲਾ ਸੀ। ਸਕੂਲ ਪੜ੍ਹਦਿਆਂ ਅਧਿਆਪਕਾਂ ਨੇ 'ਬਾਲ-ਸਭਾ' ਵਿੱਚ ਮਾਣਕ ਨੂੰ ਐਸਾ ਮੌਕਾ ਦਿੱਤਾ ਕਿ ਉਸਨੇ ਮੁੜ ਪਿੱਛੇ ਮੁੜ ਕੇ ਨਾ ਦੇਖਿਆ। ਅਧਿਆਪਕਾਂ ਦੀ ਹੱਲਾਸ਼ੇਰੀ ਨੇ ਉਸ ਅੰਦਰ ਕੁਝ ਵੱਖਰਾ ਤੇ ਵੱਡਾ ਕਰ ਗੁਜ਼ਰਨ ਦੀ ਚਿਣਗ ਲਾ ਦਿੱਤੀ। ਇਹ ਚਿਣਗ ਉਸਨੂੰ ਉਸਤਾਦ ਖੁਸ਼ੀ ਮੁਹੰਮਦ ਕੱਵਾਲ ਦੇ ਡੇਰੇ ਉੱਤੇ ਲੈ ਆਈ ਅਤੇ ਉਹ ਉਸਦਾ ਬੁਲੰਦ ਸ਼ਾਗਿਰਦ ਬਣਿਆ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('01914004-1245-481a-ac58-b910befa7276', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਈ ਸਾਲਾਂ ਚੀ ਸਖ਼ਤ ਸੰਗੀਤ ਸਾਧਨਾ ਨੇ ਆਪਣਾ ਰੰਗ ਦਿਖਾਉਣਾ ਸ਼ੁਰੂ ਕਰ ਦਿੱਤਾ। ਉਸਤਾਦ ਦੀਆਂ ਝਿੜਕਾਂ ਉਸਨੂੰ ਘਿਓ ਵਾਂਗ ਲੱਗਦੀਆਂ। ਉਸ ਨੇ ਬਹੁਤ ਸ਼ਿੱਦਤ ਨਾਲ ਰਾਗਦਾਰੀ ਦੀਆਂ ਬਰੀਕੀਆਂ ਸਿੱਖਣੀਆਂ ਸ਼ੁਰੂ ਕਰ ਦਿੱਤੀਆਂ। ਉਸ ਦੀ ਅਵਾਜ਼ ਵਿੱਚ ਲੋਹੇ ਦੀ ਬੁਲੰਦੀ ਸੀ। ਜਦੋਂ ਉਹ ਇੱਕ ਹੱਥ ਕੰਨ ਉੱਤੇ ਰੱਖ ਕੇ ਹੇਕ ਲਾਉਂਦਾ ਤਾਂ ਸੁਣਨ ਵਾਲਿਆਂ ਦੀਆਂ ਅੱਖਾਂ ਟੱਡੀਆਂ ਰਹਿ ਜਾਂਦੀਆਂ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('46d4f480-9cb4-4c21-ab12-90943c82253b', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹੁਣ ਮਾਣਕ ਆਪਣੀ ਮਿੱਥੀ ਮੰਜ਼ਲ ਵੱਲ ਹੋ ਤੁਰਿਆ। ਉਸ ਨੇ ਬਠਿੰਡਾ ਛੱਡ ਕੇ ਲੁਧਿਆਣੇ ਨੂੰ ਆਪਣਾ ਘਰ ਬਣਾ ਲਿਆ। ਉਹ ਹਰਚਰਨ ਗਰੇਵਾਲ ਤੇ ਸੀਮਾ ਨਾਲ ਸਟੇਜਾਂ ਲਾਉਣ ਲੱਗਿਆ। 1968 ਵਿੱਚ ਉਸ ਦਾ ਪਹਿਲਾ ਦੋਗਾਣਾ ਰਿਕਾਰਡ ਹੋਇਆ। ਉਸ ਸਮੇਂ ਭਾਵੇਂ ਦੋਗਾਣਾ ਗਾਇਕੀ ਦਾ ਬੋਲਬਾਲਾ ਸੀ ਪਰ ਮਾਣਕ ਨੇ ਸੋਲੋ ਗੀਤ ਗਾਉਣੇ ਸ਼ੁਰੂ ਕਰ ਦਿੱਤੇ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('a64bf88b-3ca8-459b-8ded-de0a231b836d', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਛਾਂਟਵਾਂ ਸਰੀਰ, ਮਧਰਾ ਕੱਦ ਤੇ ਬੁਲੰਦ ਅਵਾਜ਼ ਉਸਨੂੰ ਵਿਲੱਖਣ ਪਛਾਣ ਬਖਸ਼ਦੇ। ਉਹ ਮਾਈਕ ਤੋਂ ਦੂਰ ਖੜ੍ਹ ਕੇ ਗਾਉਂਦਾ ਪਰ ਮਜ਼ਾਲ ਹੈ ਸਰੋਤਿਆਂ ਤੱਕ ਅਵਾਜ਼ ਜਾਣ ਵਿੱਚ ਕੋਈ ਗੜਬੜ ਹੋਵੇ। ਇਸੇ ਦੌਰਾਨ ਉਸਦੀ ਮੁਲਾਕਾਤ ਗੀਤਕਾਰ ਹਰਦੇਵ ਦਿਲਗੀਰ (ਦੇਵ ਥਰੀਕਿਆਂ ਵਾਲਾ) ਨਾਲ ਹੋਈ। ਦੇਵ ਦੀ ਮਾਣਕ ਦੇ ਪਿੰਡ ਜਲਾਲ ਵਿਖੇ ਰਿਸ਼ਤੇਦਾਰੀ ਹੋਣ ਕਰਕੇ ਛੇਤੀ ਹੀ ਉਹ ਚੰਗੇ ਲਿਹਾਜ਼ੀ ਬਣ ਗਏ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('8dd3bb3d-81cc-4ad7-8c77-8e58e7fc09bc', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦੇਵ ਥਰੀਕਿਆਂ ਵਾਲੇ ਨੇ ਮਾਣਕ ਲਈ ਕਲੀਆਂ ਤੇ ਲੋਕ-ਗਾਥਾਵਾਂ ਲਿਖੀਆਂ। ਮਾਣਕ ਦੀ ਅਵਾਜ਼ ਵਿੱਚ ਰਿਕਾਰਡ ਹੋਈ ਕਲੀ 'ਤੇਰੇ ਟਿੱਲੇ ਤੋਂ ਅਹੁ ਸੂਰਤ ਦੀਹਦੀ ਆ ਹੀਰ ਦੀ' ਨੇ ਉਸ ਨੂੰ ਰਾਤੋ-ਰਾਤ ਸ਼ੁਹਰਤ ਦੇ ਅਸਮਾਨ ਉੱਤੇ ਪਹੁੰਚਾ ਦਿੱਤਾ। ਇਸ ਕਲੀ ਸਦਕਾ ਉਸ ਨੂੰ 'ਕਲੀਆਂ ਦਾ ਬਾਦਸ਼ਾਹ' ਦਾ ਖਿਤਾਬ ਮਿਲਿਆ। ਉਸ ਨੇ ਭਾਵੇਂ ਗਿਣਤੀ ਦੀਆਂ ਕਲੀਆਂ ਹੀ ਗਾਈਆਂ ਪਰ ਉਸ ਦੀ ਪ੍ਰਸਿੱਧੀ ਕਲੀਆਂ ਗਾਉਣ ਕਰਕੇ ਹੀ ਜ਼ਿਆਦਾ ਹੋਈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('28bd80e5-5c61-4cd7-8c41-42e493201c71', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਾਣਕ ਦੇ 'ਮਾਣਕ' ਬਣਨ ਦਾ ਕਿੱਸਾ ਵੀ ਬੜਾ ਦਿਲਚਸਪ ਹੈ। ਇੱਕ ਵਿਆਹ ਵਿੱਚ ਉਸ ਨੇ ਉਸ ਸਮੇਂ ਦੇ ਮੁੱਖ-ਮੰਤਰੀ ਸ. ਪ੍ਰਤਾਪ ਸਿੰਘ ਕੈਰੋਂ ਦੀ ਹਾਜ਼ਰੀ ਵਿੱਚ 'ਸਿਹਰਾ' ਗਾਇਆ। ਉਸ ਦੀ ਅਵਾਜ਼ ਸੁਣ ਕੇ ਕੈਰੋਂ ਸਾਹਿਬ ਨੇ ਕਿਹਾ ਕਿ ਇਹ ਮੁੰਡਾ ਤਾਂ ਮਾਣਕ ਐ, ਮਾਣਕ! ਇਸ ਤੋਂ ਉਸ ਨੇ ਹਮੇਸ਼ਾ ਲਈ ਆਪਣੇ ਨਾਂ ਨਾਲ ਮਾਣਕ ਜੋੜ ਲਿਆ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('6793946c-bb2c-4b80-a377-3c56e2c50715', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਾਣਕ ਦਾ ਯੁੱਗ ਕੈਸਟਾਂ ਦਾ ਯੁੱਗ ਸੀ। ਮੋਟਰ-ਕਾਰਾਂ ਅਤੇ ਟਰੈਕਟਰਾਂ ਉੱਤੇ ਟੇਪਾਂ ਵਿੱਚ ਕੈਸਟਾਂ ਹੀ ਮਨੋਰੰਜਨ ਕਰਦੀਆਂ ਸਨ। ਮਾਣਕ ਨੇ ਬਹੁਤ ਸਾਰੇ ਗੀਤਕਾਰਾਂ ਦੇ ਗੀਤ ਗਾਏ ਪਰ ਸਭ ਤੋਂ ਵੱਧ ਗੀਤ ਦੇਵ ਥਰੀਕਿਆਂ ਵਾਲੇ ਦੇ ਹੀ ਸਨ। ਬਾਬਾ ਬੰਦਾ ਸਿੰਘ ਬਹਾਦਰ ਦੀ ਵਾਰ 'ਲੈ ਕੇ ਕਲਗੀਧਰ ਤੋਂ ਥਾਪੜਾ' ਨੂੰ ਜਦੋਂ ਉਹ ਰੂਹ ਨਾਲ ਗਾਉਂਦਾ ਤਾਂ ਲੋਕ ਅਸ਼-ਅਸ਼ ਕਰ ਉੱਠਦੇ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('e0fa1bbc-eae0-41a0-a66b-16687d37f009', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਸ ਦੇ ਪੁਰਖੇ ਗੁਰਬਾਣੀ ਸੰਗੀਤ ਨਾਲ ਜੁੜੇ ਹੋਣ ਕਰਕੇ ਉਸ ਅੰਦਰ ਮਹਾਨ ਸਿੱਖ ਵਿਰਾਸਤ ਲਈ ਅਥਾਹ ਸਤਿਕਾਰ ਪਿਆ ਸੀ। ਉਸ ਨੇ ਸਿੱਖੀ ਲਈ ਸ਼ਹੀਦੀਆਂ ਦੇਣ ਵਾਲੇ ਯੋਧਿਆਂ ਦੀ ਸ਼ਾਨ ਵਿੱਚ ਵੀ ਬਹੁਤ ਗਾਇਆ। 'ਭਾਈ ਮਤੀ ਦਾਸ ਗੁਰੂ ਦਾ ਪਿਆਰਾ, ਮੁੱਖ ਸਤਿਨਾਮ ਬੋਲਦਾ, ਆ ਜੋ ਜੀਹਨੇ ਨੱਚਣਾ ਖੰਡੇ ਦੀ ਧਾਰ ਉੱਤੇ' ਸਮੇਤ ਕਈ ਦਰਜਨ ਧਾਰਮਿਕ ਗੀਤ ਗਾਏ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('a0304171-07ba-4d84-b03c-3b10d0a75bba', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਾਣਕ ਨੇ ਸਮਾਜਿਕ ਸਰੋਕਾਰਾਂ ਨਾਲ ਲਬਰੇਜ਼ ਗੀਤ ਵੀ ਆਪਣੀ ਗਾਇਕੀ ਦਾ ਸ਼ਿੰਗਾਰ ਬਣਾਏ, ÒÒਮੈਂ ਹੁੰਦੀ ਐਂ ਮੈਂ ਤੂੰ ਦੁਨੀਆਂ ਵਾਙੂੰ, ਛੇਤੀ ਹੋਇਆ ਕੀ ਜੇ ਧੀ ਜੰਮ ਪਈ, ਤੇਰੀ ਕੁੱਖ ਤਾਂ ਸੁਲੱਖਣੀ ਹੋਈ, ਛੇਤੀ ਕਰ ਸਰਵਣ ਪੁੱਤਰਾਂ ਪਾਣੀ ਪਿਆ ਦੇ ਤੂੰ।ÓÓ ਉਸ ਦਾ ਗਾਇਆ Òਮੈਂ ਚਾਦਰ ਕੱਢਦੀ ਨੀ, ਗਿਣ ਤੋਪੇ ਪਾਵਾਂ...Ó ਨੇ ਲੰਮਾ ਸਮਾਂ ਰੇਡੀਓ ਉੱਤੇ ਸਰਦਾਰੀ ਕੀਤੀ ਹੈ। ਮਾਣਕ ਨੇ ਭਾਰਤ ਵਿੱਚ ਹੀ ਨਹੀਂ ਬਲਕਿ ਵਿਦੇਸ਼ਾਂ ਵਿੱਚ ਵੀ ਬਹੁਤ ਸਾਰੇ ਕਾਮਯਾਬ ਅਖਾੜੇ ਲਾ ਕੇ ਆਪਣੀ ਕਲਾ ਦਾ ਲੋਹਾ ਮਨਵਾਇਆ। ਉਸ ਦੀਆਂ ਅਣਗਿਣਤ ਪੁਰਾਣੀਆਂ ਵੀਡੀਓਜ਼ ਅੱਜ-ਕੱਲ੍ਹ ਸੋਸ਼ਲ-ਮੀਡੀਆ ਉੱਤੇ ਵੀ ਵੇਖਣ ਨੂੰ ਮਿਲ ਜਾਂਦੀਆਂ ਹਨ। ਮਾਣਕ ਸੁਭਾਅ ਪੱਖੋਂ ਸਰਲ ਪਰ ਹਾਜ਼ਰ-ਜਵਾਬ ਸੀ। ਉਸ ਨੇ ਆਪਣੀ ਕਲਾ ਨੂੰ ਮਹਿਜ਼ ਆਪਣੇ ਖੀਸੇ ਭਰਨ ਤੱਕ ਸੀਮਤ ਨਹੀਂ ਰੱਖਿਆ। ਉਸ ਲਈ ਮੋਹ-ਮੁਹੱਬਤ ਬਹੁਤ ਵੱਡੀ ਚੀਜ਼ ਸੀ। ਇਸੇ ਲਈ ਉਹ ਅਖਾੜੇ ਲਈ ਬਹੁਤ ਵੱਡੀ ਕੀਮਤ ਨਹੀਂ ਸੀ ਮੰਗਦਾ। ਉਸ ਨੇ ਸੰਗੀਤ ਨੂੰ ਆਪਣੇ ਤੱਕ ਸੀਮਤ ਰੱਖਣ ਦੀ ਥਾਂ ਅਨੇਕਾਂ ਸ਼ਾਗਿਰਦਾਂ ਨੂੰ ਇਸ ਦੇ ਲੜ ਲਾਇਆ। ਪ੍ਰਸਿੱਧ ਗਾਇਕ ਜੈਜ਼ੀ ਬੈਂਸ ਮਾਣਕ ਦਾ ਹੀ ਚੇਲਾ ਹੈ। ਮਾਣਕ ਦਾ ਅੰਤਲਾ ਸਮਾਂ ਦੁਖਦਾਈ ਹਾਲਤ ਵਿੱਚ ਲੰਘਿਆ। ਉਸ ਦਾ ਪੁੱਤਰ ਯੁੱਧਵੀਰ ਮਾਣਕ ਜਿਹੜਾ ਉਸ ਵਾਂਗ ਹੀ ਬੁਲੰਦ ਆਵਾਜ਼ ਦਾ ਮਾਲਕ ਸੀ, ਇੱਕ ਭਿਆਨਕ ਬਿਮਾਰੀ ਦਾ ਸ਼ਿਕਾਰ ਹੋ ਗਿਆ। ਮਾਣਕ ਦੇ ਪਰਿਵਾਰ ਲਈ ਇਹ ਬਹੁਤ ਵੱਡੀ ਸੱਟ ਸੀ। ਕੁਝ ਸਮਾਂ ਬਿਮਾਰ ਰਹਿਣ ਮਗਰੋਂ ਅੰਤ 26, ਨਵੰਬਰ 2001 ਨੂੰ ਪੰਜਾਬ ਦੀ ਇਹ ਬੁਲੰਦ ਆਵਾਜ਼ ਹਮੇਸ਼ਾ ਲਈ ਖ਼ਾਮੋਸ਼ ਹੋ ਗਈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('12c2ea67-35cd-459b-b7aa-23f2ce080556', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਾਣਕ ਨੇ ਸਮਾਜਿਕ ਸਰੋਕਾਰਾਂ ਨਾਲ ਲਬਰੇਜ਼ ਗੀਤ ਵੀ ਆਪਣੀ ਗਾਇਕੀ ਦਾ ਸ਼ਿੰਗਾਰ ਬਣਾਏ, ÒÒਮੈਂ ਹੁੰਦੀ ਐਂ ਮੈਂ ਤੂੰ ਦੁਨੀਆਂ ਵਾਙੂੰ, ਛੇਤੀ ਹੋਇਆ ਕੀ ਜੇ ਧੀ ਜੰਮ ਪਈ, ਤੇਰੀ ਕੁੱਖ ਤਾਂ ਸੁਲੱਖਣੀ ਹੋਈ, ਛੇਤੀ ਕਰ ਸਰਵਣ ਪੁੱਤਰਾਂ ਪਾਣੀ ਪਿਆ ਦੇ ਤੂੰ।ÓÓ ਉਸ ਦਾ ਗਾਇਆ Òਮੈਂ ਚਾਦਰ ਕੱਢਦੀ ਨੀ, ਗਿਣ ਤੋਪੇ ਪਾਵਾਂ...Ó ਨੇ ਲੰਮਾ ਸਮਾਂ ਰੇਡੀਓ ਉੱਤੇ ਸਰਦਾਰੀ ਕੀਤੀ ਹੈ। ਮਾਣਕ ਨੇ ਭਾਰਤ ਵਿੱਚ ਹੀ ਨਹੀਂ ਬਲਕਿ ਵਿਦੇਸ਼ਾਂ ਵਿੱਚ ਵੀ ਬਹੁਤ ਸਾਰੇ ਕਾਮਯਾਬ ਅਖਾੜੇ ਲਾ ਕੇ ਆਪਣੀ ਕਲਾ ਦਾ ਲੋਹਾ ਮਨਵਾਇਆ। ਉਸ ਦੀਆਂ ਅਣਗਿਣਤ ਪੁਰਾਣੀਆਂ ਵੀਡੀਓਜ਼ ਅੱਜ-ਕੱਲ੍ਹ ਸੋਸ਼ਲ-ਮੀਡੀਆ ਉੱਤੇ ਵੀ ਵੇਖਣ ਨੂੰ ਮਿਲ ਜਾਂਦੀਆਂ ਹਨ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('28711ffe-ffdd-4580-ba97-9658807c4028', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਾਣਕ ਸੁਭਾਅ ਪੱਖੋਂ ਸਰਲ ਪਰ ਹਾਜ਼ਰ-ਜਵਾਬ ਸੀ। ਉਸ ਨੇ ਆਪਣੀ ਕਲਾ ਨੂੰ ਮਹਿਜ਼ ਆਪਣੇ ਖੀਸੇ ਭਰਨ ਤੱਕ ਸੀਮਤ ਨਹੀਂ ਰੱਖਿਆ। ਉਸ ਲਈ ਮੋਹ-ਮੁਹੱਬਤ ਬਹੁਤ ਵੱਡੀ ਚੀਜ਼ ਸੀ। ਇਸੇ ਲਈ ਉਹ ਅਖਾੜੇ ਲਈ ਬਹੁਤ ਵੱਡੀ ਕੀਮਤ ਨਹੀਂ ਸੀ ਮੰਗਦਾ। ਉਸ ਨੇ ਸੰਗੀਤ ਨੂੰ ਆਪਣੇ ਤੱਕ ਸੀਮਤ ਰੱਖਣ ਦੀ ਥਾਂ ਅਨੇਕਾਂ ਸ਼ਾਗਿਰਦਾਂ ਨੂੰ ਇਸ ਦੇ ਲੜ ਲਾਇਆ। ਪ੍ਰਸਿੱਧ ਗਾਇਕ ਜੈਜ਼ੀ ਬੈਂਸ ਮਾਣਕ ਦਾ ਹੀ ਚੇਲਾ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('8e5487ab-7589-4369-8313-a5aa5c8d7476', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਾਣਕ ਦਾ ਅੰਤਲਾ ਸਮਾਂ ਦੁਖਦਾਈ ਹਾਲਤ ਵਿੱਚ ਲੰਘਿਆ। ਉਸ ਦਾ ਪੁੱਤਰ ਯੁੱਧਵੀਰ ਮਾਣਕ ਜਿਹੜਾ ਉਸ ਵਾਂਗ ਹੀ ਬੁਲੰਦ ਆਵਾਜ਼ ਦਾ ਮਾਲਕ ਸੀ, ਇੱਕ ਭਿਆਨਕ ਬਿਮਾਰੀ ਦਾ ਸ਼ਿਕਾਰ ਹੋ ਗਿਆ। ਮਾਣਕ ਦੇ ਪਰਿਵਾਰ ਲਈ ਇਹ ਬਹੁਤ ਵੱਡੀ ਸੱਟ ਸੀ। ਕੁਝ ਸਮਾਂ ਬਿਮਾਰ ਰਹਿਣ ਮਗਰੋਂ ਅੰਤ 26, ਨਵੰਬਰ 2001 ਨੂੰ ਪੰਜਾਬ ਦੀ ਇਹ ਬੁਲੰਦ ਆਵਾਜ਼ ਹਮੇਸ਼ਾ ਲਈ ਖ਼ਾਮੋਸ਼ ਹੋ ਗਈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('7aeb3363-7f7b-47d4-82c1-75e159d45660', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਾਣਕ ਨੇ ਸਮਾਜਿਕ ਸਰੋਕਾਰਾਂ ਨਾਲ ਲਬਰੇਜ਼ ਗੀਤ ਵੀ ਆਪਣੀ ਗਾਇਕੀ ਦਾ ਸ਼ਿੰਗਾਰ ਬਣਾਏ, ÒÒਮੈਂ ਹੁੰਦੀ ਐਂ ਮੈਂ ਤੂੰ ਦੁਨੀਆਂ ਵਾਙੂੰ, ਛੇਤੀ ਹੋਇਆ ਕੀ ਜੇ ਧੀ ਜੰਮ ਪਈ, ਤੇਰੀ ਕੁੱਖ ਤਾਂ ਸੁਲੱਖਣੀ ਹੋਈ, ਛੇਤੀ ਕਰ ਸਰਵਣ ਪੁੱਤਰਾਂ ਪਾਣੀ ਪਿਆ ਦੇ ਤੂੰ।ÓÓ ਉਸ ਦਾ ਗਾਇਆ Òਮੈਂ ਚਾਦਰ ਕੱਢਦੀ ਨੀ, ਗਿਣ ਤੋਪੇ ਪਾਵਾਂ...Ó ਨੇ ਲੰਮਾ ਸਮਾਂ ਰੇਡੀਓ ਉੱਤੇ ਸਰਦਾਰੀ ਕੀਤੀ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e6b28cd7-fd02-477e-b59e-8eb70b1e0afb', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਾਣਕ ਨੇ ਭਾਰਤ ਵਿੱਚ ਹੀ ਨਹੀਂ ਬਲਕਿ ਵਿਦੇਸ਼ਾਂ ਵਿੱਚ ਵੀ ਬਹੁਤ ਸਾਰੇ ਕਾਮਯਾਬ ਅਖਾੜੇ ਲਾ ਕੇ ਆਪਣੀ ਕਲਾ ਦਾ ਲੋਹਾ ਮਨਵਾਇਆ। ਉਸ ਦੀਆਂ ਅਣਗਿਣਤ ਪੁਰਾਣੀਆਂ ਵੀਡੀਓਜ਼ ਅੱਜ-ਕੱਲ੍ਹ ਸੋਸ਼ਲ-ਮੀਡੀਆ ਉੱਤੇ ਵੀ ਵੇਖਣ ਨੂੰ ਮਿਲ ਜਾਂਦੀਆਂ ਹਨ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
