  ('c980b97c-b755-4b65-b459-4ac9efcf4a49', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਾਣਕ ਨੇ ਸਮਾਜਿਕ ਸਰੋਕਾਰਾਂ ਨਾਲ ਲਬਰੇਜ਼ ਗੀਤ ਵੀ ਆਪਣੀ ਗਾਇਕੀ ਦਾ ਸ਼ਿੰਗਾਰ ਬਣਾਏ, ÒÒਮੈਂ ਹੁੰਦੀ ਐਂ ਮੈਂ ਤੂੰ ਦੁਨੀਆਂ ਵਾਙੂੰ, ਛੇਤੀ ਹੋਇਆ ਕੀ ਜੇ ਧੀ ਜੰਮ ਪਈ, ਤੇਰੀ ਕੁੱਖ ਤਾਂ ਸੁਲੱਖਣੀ ਹੋਈ, ਛੇਤੀ ਕਰ ਸਰਵਣ ਪੁੱਤਰਾਂ ਪਾਣੀ ਪਿਆ ਦੇ ਤੂੰ।ÓÓ$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('aaf45486-ebf9-47a3-98a5-681a7d6771b8', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਸ ਦਾ ਗਾਇਆ Òਮੈਂ ਚਾਦਰ ਕੱਢਦੀ ਨੀ, ਗਿਣ ਤੋਪੇ ਪਾਵਾਂ...Ó ਨੇ ਲੰਮਾ ਸਮਾਂ ਰੇਡੀਓ ਉੱਤੇ ਸਰਦਾਰੀ ਕੀਤੀ ਹੈ। ਮਾਣਕ ਨੇ ਭਾਰਤ ਵਿੱਚ ਹੀ ਨਹੀਂ ਬਲਕਿ ਵਿਦੇਸ਼ਾਂ ਵਿੱਚ ਵੀ ਬਹੁਤ ਸਾਰੇ ਕਾਮਯਾਬ ਅਖਾੜੇ ਲਾ ਕੇ ਆਪਣੀ ਕਲਾ ਦਾ ਲੋਹਾ ਮਨਵਾਇਆ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('35272606-c35f-4500-9f22-c81eccd05f15', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਸ ਦੀਆਂ ਅਣਗਿਣਤ ਪੁਰਾਣੀਆਂ ਵੀਡੀਓਜ਼ ਅੱਜ-ਕੱਲ੍ਹ ਸੋਸ਼ਲ-ਮੀਡੀਆ ਉੱਤੇ ਵੀ ਵੇਖਣ ਨੂੰ ਮਿਲ ਜਾਂਦੀਆਂ ਹਨ। ਮਾਣਕ ਸੁਭਾਅ ਪੱਖੋਂ ਸਰਲ ਪਰ ਹਾਜ਼ਰ-ਜਵਾਬ ਸੀ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e203adf9-b710-4437-8206-7596224e18ff', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '89566f90-c468-41b0-90ed-8f05cba4ecbe', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਸ ਨੇ ਆਪਣੀ ਕਲਾ ਨੂੰ ਮਹਿਜ਼ ਆਪਣੇ ਖੀਸੇ ਭਰਨ ਤੱਕ ਸੀਮਤ ਨਹੀਂ ਰੱਖਿਆ। ਉਸ ਲਈ ਮੋਹ-ਮੁਹੱਬਤ ਬਹੁਤ ਵੱਡੀ ਚੀਜ਼ ਸੀ। ਇਸੇ ਲਈ ਉਹ ਅਖਾੜੇ ਲਈ ਬਹੁਤ ਵੱਡੀ ਕੀਮਤ ਨਹੀਂ ਸੀ ਮੰਗਦਾ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-506Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
